import{_ as t,a as i,o as a,a6 as d}from"./chunks/framework.CJDy2q7X.js";const l=JSON.parse('{"title":"Create Shipment","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-create-shipment","title":"Create Shipment","description":"Ship one or more order items from a chosen inventory source.","query":"mutation CreateShipment($input: createAdminShipmentInput!) {\\n  createAdminShipment(input: $input) {\\n    adminShipment { id }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"orderId\\": 2392,\\n    \\"source\\": 1,\\n    \\"items\\": [\\n      { \\"orderItemId\\": 42, \\"inventorySourceId\\": 1, \\"quantity\\": 3 }\\n    ],\\n    \\"carrierTitle\\": \\"UPS\\",\\n    \\"trackNumber\\": \\"1Z999AA1\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminShipment\\": {\\n      \\"adminShipment\\": { \\"id\\": \\"/api/admin/shipments/55\\" }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/orders/create-shipment.md","filePath":"api/graphql-api/admin/sales/orders/create-shipment.md","lastUpdated":1786429091000}'),o={name:"api/graphql-api/admin/sales/orders/create-shipment.md"};function r(n,e,s,p,c,h){return a(),i("div",null,e[0]||(e[0]=[d('<h1 id="create-shipment" tabindex="-1">Create Shipment <a class="header-anchor" href="#create-shipment" aria-label="Permalink to &quot;Create Shipment&quot;">​</a></h1><p>Ships one or more order items from a chosen inventory source. The same eligibility checks as the admin Shipment screen apply (the order must not be closed or marked fraud). Each item&#39;s requested quantity is validated against its still-shippable quantity, <code>qty_to_ship</code>, AND against the inventory available at the chosen source before the shipment is created.</p><p>For <strong>composite products</strong> (bundle, configurable, grouped), the requested quantity is split across the line&#39;s component items, and each component&#39;s own shippable quantity and stock at the chosen source are validated — so a shipment can&#39;t be created for more component stock than is physically available.</p><p>After the mutation, fetch the full shipment via <code>adminShipment(id:)</code> or the REST <code>GET /api/admin/shipments/{id}</code> endpoint.</p><div class="tip custom-block"><p class="custom-block-title">Prerequisites</p><p>The example targets an order with shippable items. If your order has no items with <code>qty_to_ship &gt; 0</code> (already fully shipped / not yet invoiced) the mutation returns <em>&quot;At least one item with a positive quantity is required.&quot;</em> — pick an order with outstanding qty to ship.</p></div><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>createAdminShipment</code></td><td>Mutation</td></tr></tbody></table><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Lang key</th><th>Message</th></tr></thead><tbody><tr><td>Order <code>closed</code></td><td><code>bagistoapi::app.admin.order.actions.shipment.closed</code></td><td>Closed orders cannot be shipped.</td></tr><tr><td>Order <code>fraud</code></td><td><code>bagistoapi::app.admin.order.actions.shipment.fraud</code></td><td>Fraud orders cannot be shipped.</td></tr><tr><td>Nothing to ship</td><td><code>bagistoapi::app.admin.order.actions.shipment.nothing-to-ship</code></td><td>There is nothing to ship on this order.</td></tr><tr><td>No permission</td><td><code>bagistoapi::app.admin.order.actions.shipment.no-permission</code></td><td>You do not have permission to ship orders.</td></tr><tr><td>Source missing</td><td><code>bagistoapi::app.admin.order.actions.shipment.source-required</code></td><td>Inventory source is required.</td></tr><tr><td>Items missing</td><td><code>bagistoapi::app.admin.order.actions.shipment.items-required</code></td><td>At least one item with a positive quantity is required.</td></tr><tr><td>Qty exceeds available</td><td><code>bagistoapi::app.admin.order.actions.shipment.qty-exceeds</code></td><td>Requested quantity (<code>:requested</code>) exceeds available quantity (<code>:available</code>) for SKU <code>:sku</code>.</td></tr><tr><td>Inventory insufficient</td><td><code>bagistoapi::app.admin.order.actions.shipment.inventory-insufficient</code></td><td>Inventory at the selected source is insufficient for SKU <code>:sku</code>.</td></tr><tr><td>Save failed</td><td><code>bagistoapi::app.admin.order.actions.shipment.failed</code></td><td>Could not create the shipment.</td></tr></tbody></table>',9)]))}const u=t(o,[["render",r]]);export{l as __pageData,u as default};
